    out=[]
    for k in range(kmin,kmax+1):
        d.clear()
        for i in range(len(s)-k+1):
            d[s[i:i+k]].append(i+1)
        for km,pos in d.items():
            r=km.translate(str.maketrans('ACGT','TGCA'))[::-1]
            if r in d:
                for p1 in d[km]:
                    for p2 in d[r]:
                        if p2>p1:
                            out.append((p1,p2,p2+k-1-(p1-1)))
    return out

